DO $$ BEGIN
  IF (SELECT count(*) FROM meal_catalog WHERE source_type = 'reference' AND price_details IS NOT NULL) <> 1145 THEN
    RAISE EXCEPTION 'Price metadata coverage mismatch; rollback required';
  END IF;
END $$;
